    match=re.search(r'%\.(\d+)',fmt)
    precision=int(match[1]) if match else 2
    precision=min(precision,100)
    opts=re.sub(r'%\.\d+','',fmt).lower()
    space=' ' if ' ' in opts else ''
    decimal='d' in opts
    conventional='c' in opts
    short='s' in opts
    chosen=None
    for unit in ['k','m','g','t','p','e']:
        if unit in opts:
            chosen='kmgtpe'.index(unit)+1
            if unit+'b' in opts:decimal=True
            break
