    elif short:unit='KMGTPE'[i-1]
    elif decimal or conventional:unit='KMGTPE'[i-1]+'B'
    else:unit='KMGTPE'[i-1]+'iB'
    return amount_str+space+unit


def scalar(name,args,record,context):
    a=args[0] if args else EMPTY
    s=a.text()
    cfg=context.config
    def arg(i):return args[i] if i<len(args) else EMPTY
    def num(i=0):return numeric(arg(i),units=False)
    def date(i=0):return parse_date(arg(i),cfg.get('us_dates',False))
    if name=='Length':return V(len(s))
    if name=='Lower':return V(s.lower())
    if name=='Upper':return V(s.upper())
    if name=='InitCap':
        return V(re.sub(r'[^\W_]+',lambda m:m[0][:1].upper()+m[0][1:].lower(),s,flags=re.UNICODE))
    if name in ('Trim','LTrim','RTrim'):
        return V({'Trim':str.strip,'LTrim':str.lstrip,'RTrim':str.rstrip}[name](s))
