            return V(base64.b64decode(s+'='*((-len(s))%4),validate=True).decode('utf-8','replace'))
        except (ValueError,base64.binascii.Error):return EMPTY
    if name=='Concat':return V(''.join(v.text() for v in args))
    if name=='ConcatWs':return V(s.join(v.text() for v in args[1:]))
    if name=='Replace':return V(s.replace(arg(1).text(),arg(2).text()))
    if name=='Locate':
        start=integer(arg(2),default=1,strict=True,unsigned=True) if len(args)>2 else 1
        if start is None:raise EvaluationError('Could not parse position argument of LOCATE function: '+arg(2).text())
        ix=s.find(arg(1).text(),max(0,start-1))
        return V(ix+1 if ix>=0 else 0)
    if name=='Substring':
