        if pos is None:raise EvaluationError('Could not parse position argument of SUBSTRING function: '+arg(1).text())
        begin=max(0,len(s)+pos) if pos<0 else max(0,pos-1)
        if len(args)>2:
            length=integer(arg(2),strict=True,unsigned=True)
            if length is None:raise EvaluationError('Could not parse length argument of SUBSTRING function: '+arg(2).text())
            return V(s[begin:begin+length])
        return V(s[begin:])
    if name=='Coalesce':return next((v for v in args if v.text()!=''),EMPTY)
    if name.startswith('Contains') and name!='Contains':
        def included(ch):
            c=ord(ch)
            hira=0x3040<=c<=0x309f
            kata=0x30a0<=c<=0x30ff or 0x31f0<=c<=0x31ff or 0xff65<=c<=0xff9f
            kanji=0x3400<=c<=0x4dbf or 0x4e00<=c<=0x9fff or 0xf900<=c<=0xfaff or 0x20000<=c<=0x2ffff
            greek=0x370<=c<=0x3ff or 0x1f00<=c<=0x1fff
            return {'ContainsJapanese':hira or kata or kanji,'ContainsKana':hira or kata,'ContainsHiragana':hira,'ContainsKatakana':kata,'ContainsKanji':kanji,'ContainsGreek':greek}.get(name,False)
        return V(any(included(c) for c in s))
    if name in ('CurrentUid','CurrentUser','CurrentGid','CurrentGroup'):
        if name=='CurrentUid':return V(os.getuid())
        if name=='CurrentGid':return V(os.getgid())
        if name=='CurrentUser':
            try:return V(pwd.getpwuid(os.getuid()).pw_name)
            except KeyError:return EMPTY
        try:return V(grp.getgrgid(os.getgid()).gr_name)
        except KeyError:return EMPTY
    if name=='CurrentDate':return V(dt.date.today().isoformat())
    if name=='CurrentTime':return V(dt.datetime.now().strftime('%H:%M:%S'))
    if name=='CurrentTimestamp':return V(dt.datetime.now().replace(microsecond=0),'date')
    if name in ('Day','Month','Year','DayOfWeek','DayName','DayOfYear','DateAdd','DateSub','DateDiff','LastDay'):
        dates=date()
        if dates is None:return EMPTY
        d=dates[0]
        if name=='Day':return V(d.day)
        if name=='Month':return V(d.month)
        if name=='Year':return V(d.year)
        if name=='DayOfWeek':return V((d.weekday()+1)%7+1)
        if name=='DayName':return V(calendar.day_name[d.weekday()])
        if name=='DayOfYear':return V(d.timetuple().tm_yday)
        if name in ('DateAdd','DateSub'):
            days=integer(arg(1),strict=True)
            if days is None:return EMPTY
            try:return V(d+dt.timedelta(days=days*(1 if name=='DateAdd' else -1)),'date')
            except OverflowError:return EMPTY
        if name=='DateDiff':
            d2=date(1)
            if d2 is None:return EMPTY
            return V(math.trunc((d-d2[0]).total_seconds()/86400))
        return V(d.replace(day=calendar.monthrange(d.year,d.month)[1]).strftime('%Y-%m-%d'))
    if name=='FromUnixtime':
        timestamp=integer(a,strict=True)
        if timestamp is None:return EMPTY
        try:return V(dt.datetime.fromtimestamp(timestamp),'date')
        except (OSError,OverflowError,ValueError):return EMPTY
    if name=='FormatSize':return V(size_format(a,arg(1).text() if len(args)>1 else cfg.get('default_file_size_format','')))
    if name=='FormatTime':
        secs=integer(a,strict=True,unsigned=True)
        if secs is None:return EMPTY
        if secs==0:return V('0μs')
        parts=[]
        for unit,n in [('d',86400),('h',3600),('m',60),('s',1)]:
            v,secs=divmod(secs,n)
            if v:parts.append(str(v)+unit)
        return V(','.join(parts))
    if name=='Pi':return V(math.pi)
    if name=='Random':
        lo,hi=0,2**63-1
        if len(args)==1:hi=integer(a,hi)
        elif len(args)>1:lo,hi=integer(a,0),integer(arg(1),hi)
        if lo>hi:lo,hi=hi,lo
        return V(random.randint(lo,hi))
    if name in ('Bin','Hex','Oct'):
        n=integer(a,strict=True)
        if n is None:return EMPTY
        if n<0:n%=2**64
        return V(format(n,{'Bin':'b','Hex':'x','Oct':'o'}[name]))
    if name in ('Least','Greatest'):
        nums=[numeric(v,units=False) for v in args]
        if not nums or any(n is None for n in nums):return EMPTY
        return V((min if name=='Least' else max)(nums))
    if name in {'Abs','Power','Sqrt','Log','Ln','Exp','Floor','Ceil','Round'}:
        n=num()
        if n is None:return EMPTY
        n=float(n)
        if name=='Abs':return V(abs(n))
        if name=='Power':
            p=num(1)
            if p is None:return EMPTY
            try:return V(math.pow(n,p))
            except OverflowError:return V(float('inf'))
            except ValueError:return V(float('nan'))
        if name=='Sqrt':
            if n<0:raise EvaluationError('SQRT of a negative number: '+number_text(n))
            return V(math.sqrt(n))
        if name in ('Log','Ln'):
            if n<=0:raise EvaluationError(name.upper()+' of a non-positive number: '+number_text(n))
            base=num(1) if len(args)>1 and name=='Log' else None
            if name=='Ln':return V(math.log(n))
            if base is None:base=10
            if base<=0 or base==1:raise EvaluationError('Invalid logarithm base: '+number_text(base))
            return V(math.log(n)/math.log(base))
        if name=='Exp':
            try:return V(math.exp(n))
            except OverflowError:return V(float('inf'))
        if not math.isfinite(n):return V(n)
        if name=='Floor':return V(math.floor(n))
        if name=='Ceil':return V(math.ceil(n))
        places=integer(arg(1),0,strict=True) if len(args)>1 else 0
        scale=10.0**max(-308,min(308,places or 0))
        n*=scale
        r=math.floor(n+0.5) if n>=0 else math.ceil(n-0.5)
        return V(r/scale)
    if record is not None:
        if name=='Contains':
            data=record.read()
            if data is None:return EMPTY
            try:return V(s in data.decode('utf-8'))
            except UnicodeError:return EMPTY
        if name in ('HasXattr','Xattr'):
            attrs=record.xattrs()
            if attrs is None:return EMPTY
            if name=='HasXattr':return V(s in attrs)
            try:return V(os.getxattr(record.full,s).decode('utf-8','replace'))
            except OSError:return EMPTY
        if name=='HasExtattr':
            flags=record.get('Extattrs',context)
            if flags.data is None:return EMPTY
            return V(s in flags.text() if s else False)
        if name in ('HasAclEntry','HasDefaultAclEntry','AclEntry','DefaultAclEntry'):
            return EMPTY
        if name=='HasCapability':
            caps=record.get('Capabilities',context).text()
            return V(s.removeprefix('cap_') in caps if s else False)
    if name.startswith('Has') or name in ('Contains','Xattr','AclEntry','DefaultAclEntry'):return EMPTY
    return EMPTY
PY"}

