        if expr.value=='Subtract':return V(a-b)
        if expr.value=='Multiply':return V(a*b)
        if b==0:raise EvaluationError('Division by zero')
        if expr.value=='Divide':return V(a/b)
        try:return V(math.fmod(a,b))
        except ValueError:return V(float('nan'))
    if k=='function':
        if expr.value in AGGREGATES:
            records=group or []
            if expr.value=='Count':return V(len(records))
            nums=[]
            if expr.args:
                for row in records:
