"""Query execution, expression evaluation, grouping, and formatting."""
import csv
import datetime as dt
import fnmatch
import functools
import html
import io
import json
import math
import os
import re
import sys
from query import AGGREGATES, Expr, Parser, QueryError
from values import Val,V,EMPTY,EvaluationError,numeric,integer,boolean,parse_date,scalar
from filesystem import Record,walk,expand_root,field_type

class Context:
    def __init__(self,config,no_errors=False):
        self.config=config
        self.no_errors=no_errors
        self.status=0
        self.outer={}
        self.aliases=set()
        self.warned=set()
        self.subcache={}
    def color(self,s):
        return s if self.config.get('no_color') else '\x1b[33m'+s+'\x1b[0m'
    def error(self,where,message,code=1):
        self.status=max(self.status,code)
        if not self.no_errors:
            sys.stderr.write(self.color(where)+': '+message+'\n')
    def warning(self,where,message):
        if (where,message) in self.warned:return
        self.warned.add((where,message))
        if not self.no_errors:sys.stderr.write(self.color(where)+': '+message+'\n')


def evaluate(expr,rec,ctx,group=None,group_values=None,aliases=None):
    if group_values is not None:
        key=expr.label(alias=False).lower()
        if key in group_values:return group_values[key]
    k=expr.kind
    if k=='literal':return V(expr.value)
    if k=='field':
        if rec is not None:return rec.get(expr.value,ctx)
        return V(None,field_type(expr.value))
    if k=='qualified':
        alias,field=expr.value.split('.',1)
        if rec is not None and rec.root.alias==alias:return rec.get(field,ctx)
        if alias in ctx.outer:return ctx.outer[alias].get(field,ctx)
        ctx.warning('query','Invalid root alias: '+alias)
        return EMPTY
    if k=='negative':return V(-numeric(evaluate(expr.args[0],rec,ctx,group,group_values,aliases),0))
    if k=='arith':
        a=numeric(evaluate(expr.args[0],rec,ctx,group,group_values,aliases),0)
        b=numeric(evaluate(expr.args[1],rec,ctx,group,group_values,aliases),0)
        a=float(a);b=float(b)
        if expr.value=='Add':return V(a+b)
        if expr.value=='Subtract':return V(a-b)
        if expr.value=='Multiply':return V(a*b)
        if b==0:raise EvaluationError('Division by zero')
        if expr.value=='Divide':return V(a/b)
        try:return V(math.fmod(a,b))
        except ValueError:return V(float('nan'))
    if k=='function':
        if expr.value in AGGREGATES:
            records=group or []
            if expr.value=='Count':return V(len(records))
            nums=[]
            if expr.args:
                for row in records:
                    value=evaluate(expr.args[0],row,ctx)
                    n=numeric(value,units=False)
                    if n is not None:nums.append(float(n))
            if not nums:return EMPTY
            kind=expr.value
            if kind=='Min':return V(min(nums))
            if kind=='Max':return V(max(nums))
            if kind=='Sum':return V(sum(nums))
            if kind=='Avg':return V(sum(nums)/len(nums))
            mean=0.0;m2=0.0
            for i,x in enumerate(nums,1):
                delta=x-mean;mean+=delta/i;m2+=delta*(x-mean)
            divisor=len(nums)-1 if kind in {'StdDevSamp','VarSamp'} else len(nums)
            if divisor<=0:return EMPTY
            variance=m2/divisor
            if kind.startswith('Std'):return V(math.sqrt(max(0,variance)))
            return V(variance)
        vals=[evaluate(e,rec,ctx,group,group_values,aliases) for e in expr.args]
        return scalar(expr.value,vals,rec,ctx)
    if k=='compare':
        a=evaluate(expr.args[0],rec,ctx,group,group_values,aliases)
        b=evaluate(expr.args[1],rec,ctx,group,group_values,aliases)
        return V(compare(a,b,expr.value,ctx))
    if k=='truth':
        val=evaluate(expr.args[0],rec,ctx,group,group_values,aliases)
        return V(val.type=='bool' and bool(val.data))
    if k=='not':return V(not truth(evaluate(expr.args[0],rec,ctx,group,group_values,aliases)))
    if k=='logic':
        left=truth(evaluate(expr.args[0],rec,ctx,group,group_values,aliases))
        if expr.value=='and':return V(left and truth(evaluate(expr.args[1],rec,ctx,group,group_values,aliases)))
        return V(left or truth(evaluate(expr.args[1],rec,ctx,group,group_values,aliases)))
    if k=='between':
        a,b,c=[evaluate(e,rec,ctx,group,group_values,aliases) for e in expr.args]
        return V(compare(a,b,'ge',ctx) and compare(a,c,'le',ctx))
    if k=='in':
        a=evaluate(expr.args[0],rec,ctx,group,group_values,aliases)
        return V(any(compare(a,evaluate(e,rec,ctx,group,group_values,aliases),'eq',ctx) for e in expr.args[1:]))
    if k in ('exists','inquery'):
        old=ctx.outer.copy()
        if rec is not None and rec.root.alias:ctx.outer[rec.root.alias]=rec
        try:
            rows=execute(expr.value,ctx,internal=True)
        finally:ctx.outer=old
        if k=='exists':return V(bool(rows))
        a=evaluate(expr.args[0],rec,ctx,group,group_values,aliases)
        return V(any(row[0] and compare(a,row[0][0],'eq',ctx) for row in rows))
    return EMPTY


def truth(val):return val.type=='bool' and bool(val.data)


def compare(a,b,op,ctx):
    if a.data is None or b.data is None:
        return op in {'ne','ene','notlike','notrx'} and a.data is not b.data
    if op in ('rx','notrx','like','notlike'):
        pattern=b.text()
        try:
            if op in ('like','notlike'):
                pattern='^'+''.join('.*' if c=='%' else '.' if c=='_' else re.escape(c) for c in pattern)+'$'
                matched=re.search(pattern,a.text(),re.I|re.S) is not None
            else:
                matched=re.search(pattern,a.text()) is not None
        except re.error:
            ctx.error('expression','Incorrect regex expression: '+b.text())
            return False
        return not matched if op in ('notrx','notlike') else matched
    if a.type=='date':
        d=parse_date(b,ctx.config.get('us_dates',False))
        if d is None:return False
        left=a.data
        if op=='eq':return d[0]<=left<=d[1]
        if op=='ne':return not d[0]<=left<=d[1]
        right=d[0]
    elif a.type=='int':
        left=a.data;right=integer(b,0)
    elif a.type=='float':left=a.data;right=numeric(b,0)
    elif a.type=='bool':left=bool(a.data);right=boolean(b)
    else:
        left=a.text();right=b.text()
        if op in ('eq','ne') and ('*' in right or '?' in right):
            # Shell-style matching is case insensitive; strict equality bypasses it.
            try:matched=re.fullmatch(fnmatch.translate(right),left,re.I|re.S) is not None
            except re.error:matched=False
            return matched if op=='eq' else not matched
    if op in ('eq','eeq'):return left==right
    if op in ('ne','ene'):return left!=right
    if op=='gt':return left>right
    if op=='ge':return left>=right
    if op=='lt':return left<right
    if op=='le':return left<=right
    return False


def validation(q,ctx):
    aliases={r.alias for r in q.roots if r.alias}|set(ctx.outer)
    if not aliases:return True
    valid=True
    def check(e):
        nonlocal valid
        if e is None:return
        if e.kind=='qualified':
            a=e.value.split('.',1)[0]
            if a not in aliases:
                ctx.warning('query','Invalid root alias: '+a);valid=False
        elif e.kind=='literal' and re.fullmatch(r'[A-Za-z_][\w-]*\.[A-Za-z_][\w-]*',str(e.value)):
            a=e.value.split('.',1)[0]
            if a not in aliases:
                ctx.warning('query','Invalid root alias: '+a);valid=False
        for arg in e.args:
            if isinstance(arg,Expr):check(arg)
    for e in q.columns+q.groups+[e for e,d in q.orders]+[q.condition]:check(e)
    return valid


def sort_compare(a,b):
    va,vb=a,b
    if va.data is None and vb.data is None:return 0
    if va.data is None:return -1
    if vb.data is None:return 1
    if va.type in {'int','float'} and vb.type in {'int','float'}:
        x,y=va.data,vb.data
    elif va.type=='date' and vb.type=='date':x,y=va.data,vb.data
    elif va.type=='bool' and vb.type=='bool':x,y=va.data,vb.data
    else:x,y=va.text(),vb.text()
    return (x>y)-(x<y)


def execute(q,ctx,internal=False):
    if not validation(q,ctx):return []
    aggregated=q.aggregated()
    aliases={c.alias.lower():c for c in q.columns if c.alias}
    def resolve(e):
        if e.kind=='literal' and str(e.value).lower() in aliases:return aliases[str(e.value).lower()]
        return e
    selected=[]
    match_count=0
    done=False
    for base in q.roots:
        for root in expand_root(base,ctx):
            for rec in walk(root,ctx):
                try:
                    if q.condition is not None and not truth(evaluate(q.condition,rec,ctx)):continue
                except EvaluationError as ex:
                    ctx.error(ex.where or rec.full,str(ex));continue
                match_count+=1
                if aggregated:
                    selected.append(rec)
                else:
                    if not q.orders and match_count<=q.offset:continue
                    vals=None
                    try:
                        vals=[evaluate(c,rec,ctx) for c in q.columns]
                        keys=[evaluate(resolve(e),rec,ctx) for e,desc in q.orders]
                    except EvaluationError as ex:
                        ctx.error(ex.where or rec.full,str(ex))
                    if vals is not None:
                        selected.append((vals,rec.archive,keys))
                    if not q.orders and q.limit and match_count>=q.offset+q.limit:
                        done=True;break
            if done:break
        if done:break
    rows=[]
    if aggregated:
        groups={}
        if not q.groups:groups[()]=({},selected)
        else:
            for rec in selected:
                try:
                    values=[evaluate(resolve(e),rec,ctx) for e in q.groups]
                except EvaluationError as ex:
                    ctx.error(ex.where or rec.full,str(ex));continue
                key=tuple(v.text() for v in values)
                if key not in groups:
                    mapped={e.label(alias=False).lower():v for e,v in zip(q.groups,values)}
                    groups[key]=(mapped,[])
                groups[key][1].append(rec)
        for mapped,records in groups.values():
            try:
                vals=[evaluate(c,None,ctx,records,mapped) for c in q.columns]
                keys=[evaluate(resolve(e),None,ctx,records,mapped) for e,desc in q.orders]
            except EvaluationError as ex:
                ctx.error(ex.where or 'expression',str(ex));continue
            rows.append((vals,None,keys))
    else:rows=selected
    if q.orders:
        def cmp(a,b):
            for i,(e,desc) in enumerate(q.orders):
                c=sort_compare(a[2][i],b[2][i])
                if c:return -c if desc else c
            return 0
        rows.sort(key=functools.cmp_to_key(cmp))
    if aggregated or q.orders:
        rows=rows[q.offset:]
        if q.limit:rows=rows[:q.limit]
    return rows


def format_output(q,rows):
    fmt=q.format
    if fmt=='json':
        result=[]
        for vals,arc,*_ in rows:
            obj={}
            if arc is not None:obj['archive']='['+arc+']'
            for col,val in zip(q.columns,vals):
                key=col.label()
                if q.aggregated():key=key.lower()
                obj[key]=val.text()
            result.append(obj)
        return json.dumps(result,ensure_ascii=False,sort_keys=True,separators=(',',':'))
    if fmt=='html':
        title=q.text
        out='<html><head><title>'+title+'</title></head><body><table><tr><th colspan="'+str(len(q.columns))+'">'+title+'</th></tr>'
        for vals,arc,*_ in rows:
            cells=([V('['+arc+']')] if arc is not None else [])+vals
            out+='<tr>'+''.join('<td>'+html.escape(c.text(),quote=False)+'</td>' for c in cells)+'</tr>'
        return out+'</table></body></html>'
    if fmt=='csv':
        stream=io.StringIO(newline='')
        writer=csv.writer(stream,lineterminator='\n')
        for vals,arc,*_ in rows:
            cells=([V('['+arc+']')] if arc is not None else [])+vals
            writer.writerow([c.text() for c in cells])
        return stream.getvalue()
    out=[]
    for vals,arc,*_ in rows:
        cells=([V('['+arc+']')] if arc is not None else [])+vals
        if fmt=='tabs':out.append('\t'.join(c.text() for c in cells)+'\n')
        elif fmt=='lines':out.append(''.join(c.text()+'\n' for c in cells))
        elif fmt=='list':out.append(''.join(c.text()+'\0' for c in cells))
    return ''.join(out)


def run_query(text,context):
    try:q=Parser(text).parse()
    except QueryError as ex:
        context.error('query',str(ex),2)
        return context.status
    rows=execute(q,context)
    output=format_output(q,rows)
    sys.stdout.write(output)
    return context.status
