#!/usr/bin/env python3
"""Command-line front end to the independently implemented file query engine."""
import ast
import json
import os
import re
import sys
from filesystem import default_config
from engine import Context,run_query
from help_text import HELP

USAGE=HELP.split('\n\nFiles Detected',1)[0]+'\n'
SHORT_NOTE='\nFor more detailed instructions please refer to the URL above or run fselect --help\n'


def load_config(path=None):
    config=default_config()
    explicit=path is not None
    if path is None:
        base=os.environ.get('XDG_CONFIG_HOME',os.path.join(os.path.expanduser('~'),'.config'))
        path=os.path.join(base,'fselect','config.toml')
        if not os.path.exists(path):
            local=os.path.join(os.path.dirname(os.path.abspath(sys.argv[0])),'config.toml')
            if os.path.isfile(local):path=local
    try:
        with open(path,encoding='utf8') as f:text=f.read()
    except OSError:
        if explicit:sys.stderr.write('Could not open config file. Using default settings.\n')
        else:
            try:
                os.makedirs(os.path.dirname(path),exist_ok=True)
                with open(path,'w',encoding='utf8') as f:
                    # A plain, user-editable set of defaults.
                    for k,v in config.items():
                        if isinstance(v,bool):v='true' if v else 'false'
                        elif isinstance(v,str):v=json.dumps(v)
                        elif isinstance(v,list):v='[\n'+''.join('    '+json.dumps(x)+',\n' for x in v)+']'
                        f.write(k+' = '+v+'\n')
            except OSError:pass
        return config
    try:
        for m in re.finditer(r'(?m)^\s*(\w+)\s*=\s*(\[[\s\S]*?\]|"(?:[^"\\]|\\.)*"|\x27[^\x27]*\x27|[^\n#]+)',text):
            key,val=m[1],m[2].strip()
            if val.lower() in ('true','false'):value=val.lower()=='true'
            elif val.startswith('['):value=ast.literal_eval(re.sub(r'#.*','',val))
            elif val.startswith(('"',"'")):value=ast.literal_eval(val)
            else:value=int(val)
            if key in config:config[key]=value
    except (ValueError,SyntaxError):
        sys.stderr.write('Could not parse config file. Using default settings.\n')
        return default_config()
    return config


def uncolor(text):return re.sub(r'\x1b\[[0-9;]*m','',text)


def interactive(config,no_errors=False):
    ctx=Context(config,no_errors)
    tty=sys.stdin.isatty()
    while True:
        try:
            if tty:
                line=input('fselect> ')
            else:
                line=sys.stdin.readline()
                if not line:break
                line=line.rstrip('\r\n')
        except (EOFError,KeyboardInterrupt):break
        line=line.strip()
        if not line:continue
        low=line.lower()
        if low in ('exit','quit'):break
        if low=='pwd':print(os.getcwd());continue
        if low=='help':print(uncolor(HELP) if config.get('no_color') else HELP,end='');continue
        if low=='cd' or low.startswith('cd '):
            path=line[3:].strip().strip('"\'`') if len(line)>2 else os.path.expanduser('~')
            try:os.chdir(os.path.expanduser(path))
            except OSError as ex:ctx.error(path,str(ex))
            continue
        if low.startswith('errors'):
            parts=low.split()
            if len(parts)>1 and parts[1] in ('on','off'):ctx.no_errors=parts[1]=='off'
            print('Errors are '+ctx.color('OFF' if ctx.no_errors else 'ON'))
            continue
        ctx.status=0;ctx.warned.clear()
        run_query(line,ctx)
        sys.stdout.flush()
    return 0


def main():
    args=sys.argv[1:]
    no_color='NO_COLOR' in os.environ
    # Help and version requests are recognized in the initial argument only.
    first=args[0].lower() if args else ''
    help_requested=('help' in first or first in ('-h','/?','/h'))
    version_requested=('version' in first or first in ('-v','/v'))
    config_path=None
    no_errors=False
    interactive_mode=False
    remaining=list(args)
    while remaining:
        lo=remaining[0].lower()
        if '--nocolor' in lo or '--no-color' in lo or '/nocolor' in lo:
            no_color=True;remaining.pop(0)
        elif '--no-errors' in lo:
            no_errors=True;remaining.pop(0)
        elif '--us-dates' in lo:
            remaining.pop(0)
        elif lo in ('--config','-c','/config'):
            remaining.pop(0)
            if not remaining:
                sys.stderr.write('Error: --config requires a path argument\n');return 2
            config_path=remaining.pop(0)
        elif lo in ('--interactive','-i','/i'):
            remaining.pop(0);interactive_mode=True
        else:break
    config=load_config(config_path)
    if no_color:config['no_color']=True
    if any('--us-dates' in a.lower() for a in args):config['us_dates']=True
    if help_requested:
        sys.stdout.write(uncolor(HELP) if config.get('no_color') else HELP);return 0
    if version_requested:
        sys.stdout.write(uncolor(USAGE) if config.get('no_color') else USAGE);return 0
    if interactive_mode:return interactive(config,no_errors)
    if not remaining:
        s=USAGE+SHORT_NOTE
        sys.stdout.write(uncolor(s) if config.get('no_color') else s);return 0
    text=' '.join(remaining)
    context=Context(config,no_errors)
    return run_query(text,context)

if __name__=='__main__':
    try:sys.exit(main())
    except BrokenPipeError:
        try:sys.stdout.close()
        except OSError:pass
        sys.exit(0)
